import createClient, { type Middleware } from "openapi-fetch";
import type { paths } from "./schema";
import { SERVER_API_URL } from "@/lib/apiBase";

// Typed API clients, from the API's contract (./schema.d.ts, generated by
// `pnpm api:generate`). Paths, parameters, bodies and responses are checked
// at compile time:
//
//   const { data, error } = await browserApi.PATCH("/me/locale", { body: { locale: "en" } });
//
// The older untyped helper (lib/apiClient.ts) still serves pages not moved yet.

export type { paths };

// The page's language (<html lang>), so the API answers errors in it.
const locale: Middleware = {
  onRequest({ request }) {
    if (typeof document !== "undefined" && document.documentElement.lang) {
      request.headers.set("X-Tracecart-Locale", document.documentElement.lang);
    }
    return request;
  },
};

/** In the browser: through the Route Handler proxy, which attaches the Clerk session. */
export const browserApi = createClient<paths>({ baseUrl: "/api/tracecart", cache: "no-store" });
browserApi.use(locale);

/** On the server (layouts, server components, route handlers): straight to the API with the session token. */
export function apiWithToken(token: string | null) {
  return createClient<paths>({
    baseUrl: SERVER_API_URL,
    cache: "no-store",
    headers: token ? { Authorization: `Bearer ${token}` } : {},
  });
}
